	    public void EncodeBase64NVARCHARFields(AccountingSettingPM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.QBOrealMeID)) //T4 find type == nText 
            {
                entityPM.QBOrealMeID = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.QBOrealMeID));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.RefreshToken)) //T4 find type == nText 
            {
                entityPM.RefreshToken = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.RefreshToken));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
		}
